/* ============ COURSE_BY_CODE ============ */
var COURSE_BY_CODE = {};
Object.keys(COURSES_DB).forEach(function(name){
  var info = COURSES_DB[name];
  if(!COURSE_BY_CODE[info.code]) COURSE_BY_CODE[info.code] = [];
  COURSE_BY_CODE[info.code].push(name);
  (info.aliases || []).forEach(function(a){
    if(typeof a === 'string' && /^\d+$/.test(a)){
      if(!COURSE_BY_CODE[a]) COURSE_BY_CODE[a] = [];
      if(COURSE_BY_CODE[a].indexOf(name) === -1) COURSE_BY_CODE[a].push(name);
    }
  });
});

/* ============ دوال البحث ============ */
function findCourseByCode(code){
  code = String(code || '').trim();
  if(!code) return null;
  var normalized = code.replace(/^0+/, '');
  if(!normalized) return null;

  var keys = Object.keys(COURSES_DB);
  for(var i = 0; i < keys.length; i++){
    var info = COURSES_DB[keys[i]];
    if(String(info.code).replace(/^0+/, '') === normalized){
      return { name: keys[i], info: info };
    }
    if(info.aliases){
      for(var a = 0; a < info.aliases.length; a++){
        var av = info.aliases[a];
        if(typeof av === 'string'){
          if(av.replace(/^0+/, '') === normalized){
            return { name: keys[i], info: info };
          }
          /* Also match by name */
          if(av === code || av === code.trim()) return { name: keys[i], info: info };
        }
      }
    }
  }
  return null;
}

function searchCourses(query){
  query = String(query || '').trim().toLowerCase();
  if(!query) return [];
  var results = [];
  Object.keys(COURSES_DB).forEach(function(name){
    var info = COURSES_DB[name];
    if(name.toLowerCase().indexOf(query) > -1 || info.code.indexOf(query) > -1){
      results.push({ name: name, info: info });
    }
  });
  return results;
}

function validateCoursesDB(){
  var issues = [];
  Object.keys(COURSE_BY_CODE).forEach(function(code){
    var uniq = [];
    COURSE_BY_CODE[code].forEach(function(n){ if(uniq.indexOf(n) === -1) uniq.push(n); });
    if(uniq.length > 1){
      issues.push('⚠️ كود مكرر: ' + code + ' → ' + uniq.join(' | '));
    }
  });
  Object.keys(COURSES_DB).forEach(function(name){
    (COURSES_DB[name].pre || []).forEach(function(p){
      if(!COURSES_DB[p]) issues.push('🔗 متطلب مفقود في "' + name + '": ' + p);
    });
  });
  var totals = {};
  Object.keys(COURSES_DB).forEach(function(name){
    var t = COURSES_DB[name].t;
    if(!totals[t]) totals[t] = 0;
    totals[t] += COURSES_DB[name].h;
  });
  var expected = { 'uni-c': 18, 'faculty': 33, 'major-c': 88 };
  Object.keys(expected).forEach(function(k){
    if(totals[k] !== expected[k]){
      issues.push('📊 ' + (COURSE_TYPES[k].label) + ': ' + totals[k] + ' (المتوقع ' + expected[k] + ')');
    }
  });
  if(issues.length === 0){
    console.log('✅ COURSES_DB صالح 100% — ' + Object.keys(COURSES_DB).length + ' مادة');
  } else {
    console.warn('⚠️ COURSES_DB فيه ' + issues.length + ' مشكلة:');
    issues.forEach(function(i){ console.warn('  ' + i); });
  }
  return issues;
}

