          if(e.date === addDaysStr(d, 1) && cur >= 20 * 60 && cur < 22 * 60) fire(d + '_examEve_' + id, '📝 امتحانك بكرة', (e.name || '') + (e.course ? ' — ' + e.course : '') + (e.time ? ' · ' + e.time : '') + ' — نام بدري وجهّز أغراضك', 'exams');
