  var PARK = [[150, 130, 44, 44, -30], [558, 247, 38, 38, 0], [673, 402, 40, 40, 0], [28, 420, 76, 62, 38], [255, 430, 38, 38, 0], [525, 520, 34, 34, 0], [432, 897, 76, 104, 0]];
